		    ext4_should_journal_data(inode) &&
		    S_ISREG(inode->i_mode) && inode->i_data.nrpages) {
			journal_t *journal = EXT4_SB(inode->i_sb)->s_journal;
			tid_t commit_tid = EXT4_I(inode)->i_datasync_tid;

